    meaning: "बेटे और भांजा बुजुर्गों के बाद आवाज देते हैं; अगली पीढ़ी सूची में आ गई। घर में हम अपनी लड़ाई बच्चों तक पहुँचा देते हैं। उन्हें पास रख सकते हो, पूरा झगड़ा सौंपे बिना।",
