    meaning: "धृतराष्ट्र के पुत्रों ने युद्ध चाहा, आवाज फिर भी सीने में चुभती है। हम झगड़ा चुनते हैं, फिर जब वह सच हो जाए तो सिकुड़ जाते हैं। वह सिकुड़न छिपाने की चीज नहीं; मान लो कि तुम भी हिल गए हो।",
