    context: "वह खुशी नहीं देख पाता। हमलावर सही, मारना फिर भी पाप लगता है।",
    relevance: "बेहाल लोगों को हराने के बाद कैसी खुशी बचती है, आज यह पूछो।",
    meaning: "धृतराष्ट्र के पुत्रों की मृत्यु में आनंद नहीं दिखता। वे हमलावर हैं, बेहाल भी हैं। दफ्तर या अदालत की कड़वी जीत के बाद जगह अक्सर उतनी हल्की नहीं होती जितनी सोची थी; उनकी बेचैनी तुम्हारे हाथ साफ नहीं कर देती।",
