    relevance: "अपने लोगों को चोट पहुँचाने से साफ रास्ता चाहना, कमजोरी नहीं है।",
    meaning: "बंधुओं को मारना शोभा नहीं देता, माधव। परिवार जीत वाले रास्ते से ज्यादा दयालु निकास खोजते हैं। आज न मिले, तो भी यह चाह तुम्हें इंसान बनाए रखती है।",
