    meaning: "हाय—लालच में अपने को मारने को तैयार; अजीब लगना ही बात है। हम अब भी पड़ोसी, सहकर्मी, भाई-बहन को पद या घर के लिए दे बैठते हैं। अगर सौदा दिन की रोशनी में भद्दा लगे, उस नजर पर भरोसा करो, कर्तव्य कहने से पहले।",
