    relevance: "और मेहनत जोड़ने से पहले पूछो, मन असल में किसकी सेवा कर रहा है।",
    meaning: "जो सिर्फ नतीजे के पीछे भागते हैं, वे दीन कहे गए—किराया मायने रखता है। सवाल यह है क्या पूरा दिन केवल पीछा है। खुद को समेटो, फिर चलो।",
