    meaning: "सब काम प्रकृति के गुण करते हैं, अहंकार से अंधा सोचता है—यह मैं कर रहा हूँ। जिम्मेदारी मिटती नहीं; अकेले मैंने किया यह कहानी तंग है, क्योंकि बीमारी, हुनर, मौसम, दूसरे लोग पहले से कमरे में थे। नरम मैं सफलता और हार दोनों को थामना आसान करता है।",
