    relevance: "आज एक मिजाज अपना काम करता देखो। यह तय मत करो कि वही मिजाज असली तुम हो।",
    meaning: "जो गुण और कर्म का भेद जानता है, वह नहीं चिपकता; वह देखता है—गुण ही गुणों के बीच खेल रहे हैं। गुस्सा देरी से मिलता है, नमी बच्चे से—कोई भी पूरा व्यक्ति नहीं। दफ्तर में एक कड़वे पत्र के बाद खुद को हमेशा का कड़वा मत मानो; माफी माँग सकते हो बिना पत्र बने।",
