    meaning: "गुणों में मोहित लोग उन्हीं के काम में फँसते हैं; पूरा जानने वाला अधूरे जानने वालों को विचलित न करे। कोशिश करते दोस्त से कहना कि कुछ मायने नहीं रखता, लुभावना है, अक्सर उन्हें अभी वह कोशिश चाहिए। उनकी मेहनत बचाओ, अपनी समझ से उन्हें छोटा मत करो।",
