    context: "अनुष्ठान का श्लोक विश्वदृष्टि बन जाता है: करने वाला, सामग्री, आग—सब ब्रह्म।",
    relevance: "कुछ मिनट काम, औजार, और करने वाले को एक ही खेत मानो।",
    meaning: "जिसका मन ऐसे कर्म में समाया हो, वह ब्रह्म तक पहुँचता है। बचता हुआ मैं काम बटोरता नहीं। प्याला धोना यही हो सकता है अगर तुम अपने को पवित्र धोने वाला कहना बंद करो।",
