    relevance: "ईमानदार दिन का काम उतनी दूर ले जा सकता है जितनी लंबी सोच।",
    meaning: "ज्ञान से जो ऊँचाई मिलती है, वही कर्म-योग से भी। जो इन्हें एक देखता है, वही सच देखता है। टोली चुनने की जरूरत नहीं, दोनों एक मंजिल की ओर हैं।",
