    relevance: "देखो किस पर भरोसा बनाए रखते हो। वही चुपचाप तुम्हें बना रहा है।",
    meaning: "श्रद्धा स्वभाव का रंग लेती है, समय के साथ तुम वही बनते हो जिस पर भरोसा करते हो। सिर्फ जल्दी पर भरोसा करो तो हड़बड़ी बन जाते हो, शांत भले पर भरोसा करो तो स्थिर होते हो। बच्चे और साथी पहले से जानते हैं तुम कौन-सा जी रहे हो।",
