    meaning: "कुछ लोग कठोर साधना ले लेते हैं जिसकी विधि ने माँग नहीं की, कठिनाई अपने आप अच्छाई नहीं। कड़ा परहेज या सबके सामने व्रत कभी-कभी जीतने की ज़रूरत छिपाता है। अपने शरीर पर दया रखने की इजाज़त है।",
