export function englishInsight(verse: GitaVerse): VerseInsight {
  return {
    translation: verse.translation,
    context: verse.context,
    relevance: verse.relevance,
    meaning: verse.meaning,
  };
}

export function insightFor(verse: GitaVerse, locale: Locale): VerseInsight {
  if (locale === "hi") {
    return verseHi[`${verse.chapter}.${verse.verse}`] ?? englishInsight(verse);
  }
  return englishInsight(verse);
}
